const techInfo={astro:['Astro','Fast public pages','https://docs.astro.build/en/concepts/islands/'],storyblok:['Storyblok','Editor studio · candidate','https://www.storyblok.com/docs'],django:['Django','Access & connections','https://docs.djangoproject.com/'],python:['Python','Backend language','https://docs.python.org/3/']};
function techBadge(key){const t=techInfo[key];return '<a class="tech-badge '+key+'" href="'+t[2]+'" target="_blank" rel="noopener"><img src="assets/'+key+'.svg" width="28" height="28" alt=""><span><strong>'+t[0]+'</strong><small>'+t[1]+'</small></span>'+icon('arrow')+'</a>'}
const techDock=document.createElement('div');techDock.className='tech-dock';techDock.innerHTML='<div><span class="kicker">CURIOUS ABOUT THE TECHNOLOGY?</span><p>Four tools. A job for each.</p></div><div class="tech-badges">'+Object.keys(techInfo).map(techBadge).join('')+'</div><small>Proposed delivery stack · this walkthrough is a lightweight simulation. Storyblok requires an editor trial.</small>';document.querySelector('.platform-bottom').replaceWith(techDock);
capabilities.public.title='Research that opens a business conversation.';capabilities.public.description='Lead with Return on Equality. Make useful insights discoverable, then give visitors a clear next step.';capabilities.public.outcomes=['Public insight before the member gate','Research connected to business value','Clear routes to membership and enquiries'];capabilities.public.instruction='Explore → preview → choose a next step';
capabilities.public.demo=()=>windowFrame('Public research journey','<div class="journey-demo"><div class="journey-breadcrumb">OUT LEADERSHIP / RESEARCH</div><span class="journey-chip">PUBLIC INSIGHT</span><h4>Equality is a business advantage.</h4><p>Discover the research. Understand its business relevance. Choose how to go deeper.</p><div class="research-art" aria-hidden="true"><i></i><i></i><i></i><i></i><span>Return on Equality™</span></div><button class="demo-btn" id="research-explore">Explore a research preview '+icon('arrow')+'</button><div id="research-result" role="status"></div></div>');
