capabilities.portal.demo=()=>windowFrame('Member access · simulation','<div class="journey-demo"><div class="role-switch" role="group" aria-label="Simulated access"><button data-access="visitor" aria-pressed="true">'+icon('globe')+' Visitor</button><button data-access="member" aria-pressed="false">'+icon('people')+' Member</button></div><div class="resource-sample"><span class="resource-cover">'+icon('book')+'<small>MEMBER RESOURCE</small><strong>Leadership<br>toolkit</strong></span><div><span class="journey-chip">MEMBERS ONLY</span><h4>Leadership resource collection</h4><p>A public summary stays visible. Full resources require verified membership.</p></div></div><button class="demo-btn" id="access-open">Check resource access '+icon('arrow')+'</button><div id="access-result" role="status"></div><small class="simulation-note">Sample roles only. No real sign-in or protected file is connected.</small></div>');
capabilities.micro.title='Different research. One connected ecosystem.';capabilities.micro.description='Keep each research property distinctive, while connecting discovery, membership and agreed lead capture.';capabilities.micro.outcomes=['Preserve useful existing work','Shared navigation and brand foundations','A deliberate next step back to Out Leadership'];capabilities.micro.scope='State Climate Index, Out to Succeed and OutQUORUM provide the existing context. Audit and reuse approved components; do not assume all three sites are rebuilt in the MVP. Agree the first template, domains, content ownership and cross-site analytics.';capabilities.micro.instruction='Choose a research property, then follow the connection';
capabilities.micro.demo=()=>windowFrame('Connected research properties','<div class="journey-demo"><div class="property-switch" role="group" aria-label="Research property"><button data-property="climate" aria-pressed="true">Climate Index</button><button data-property="succeed" aria-pressed="false">Out to Succeed</button><button data-property="quorum" aria-pressed="false">OutQUORUM</button></div><div id="property-preview" class="property-preview"></div><button class="demo-btn" id="property-connect">See the shared pathway '+icon('connect')+'</button><div id="property-result" role="status"></div></div>');
capabilities.crm.title='Make the next step measurable.';capabilities.crm.description='Connect agreed research requests and enquiries to HubSpot, with clear consent and visible completion.';capabilities.crm.outcomes=['Capture approved visitor details','Measure submission completion','Handle duplicates and connection failures'];capabilities.crm.scope='The estate review identifies HubSpot. Confirm current configuration, permissions, field mapping, consent, sandbox and sync direction. Django owns credentials and integration. The demonstration sends no personal data or real contacts.';
const originalWire=wireDemo;
wireDemo=function(key){if(key==='public'){document.querySelector('#research-explore').onclick=()=>{document.querySelector('#research-result').innerHTML='<div class="research-preview"><span class="kicker">THE NEXT STEP IS CLEAR</span><strong>Read the insight. Choose how to engage.</strong><div><button class="demo-btn" id="research-member">Explore membership '+icon('people')+'</button><button class="demo-btn" id="research-enquiry">Request a briefing '+icon('mail')+'</button></div></div>';document.querySelector('#research-member').onclick=()=>setCapability('portal');document.querySelector('#research-enquiry').onclick=()=>setCapability('crm')};return}if(key==='portal'){let member=false;document.querySelectorAll('[data-access]').forEach(b=>b.onclick=()=>{member=b.dataset.access==='member';document.querySelectorAll('[data-access]').forEach(n=>n.setAttribute('aria-pressed',n===b));document.querySelector('#access-result').textContent='';});document.querySelector('#access-open').onclick=()=>document.querySelector('#access-result').innerHTML=notice(member?'Sample permission granted. A verified member would receive the resource through Django.':'Sample permission denied. The public summary is visible; the full resource needs member sign-in.');return}if(key==='micro'){const properties={climate:['STATE CLIMATE INDEX','Explore the business climate.','A focused research tool, connected to the wider mission.'],succeed:['OUT TO SUCCEED','Make talent potential visible.','A distinct research experience with shared pathways.'],quorum:['OUTQUORUM','Explore leadership representation.','A focused property within the same digital ecosystem.']};function choose(k){const p=properties[k];document.querySelector('#property-preview').innerHTML='<span class="journey-chip">'+p[0]+'</span><h4>'+p[1]+'</h4><p>'+p[2]+'</p><div class="mini-map" aria-hidden="true">'+icon('chart')+icon('people')+icon('globe')+'</div>';document.querySelector('#property-result').textContent=''}document.querySelectorAll('[data-property]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-property]').forEach(n=>n.setAttribute('aria-pressed',n===b));choose(b.dataset.property)});document.querySelector('#property-connect').onclick=()=>document.querySelector('#property-result').innerHTML='<div class="connection-path"><span>'+icon('book')+' Research property</span>'+icon('arrow')+'<span>'+icon('globe')+' Out Leadership</span>'+icon('arrow')+'<span>'+icon('mail')+' Agreed lead capture</span></div><p class="simulation-note">Illustrative shared pathway. Existing sites remain subject to a reuse and integration audit.</p>';choose('climate');return}originalWire(key)};
const handoffs=[{name:'An editor publishes',icon:'edit',front:'Create the content model, approved blocks and preview. Editors change content within a stable layout.',back:'Agree which published items are public and which belong to members. Keep protected files out of public builds.',result:'The team can update content without rebuilding the design.',tech:['storyblok','astro'],visual:'content'},{name:'Access is checked',icon:'shield',front:'Build clear sign-in, loading and permission messages. Never present a hidden button as a security boundary.',back:'Verify identity and membership on every protected request. Return only the resources this member may access.',result:'Public visitors see the summary. Verified members can go deeper.',tech:['django','python'],visual:'access'},{name:'A member uses it',icon:'people',front:'Present useful resources and events across phone and desktop, with keyboard access and direct links.',back:'Deliver protected resources through authorized services. Handle expired sessions and unavailable resources.',result:'A member reaches the right resource through a coherent experience.',tech:['django','python'],visual:'member'},{name:'The teams verify it',icon:'check',front:'Test content changes, responsive layouts, accessibility, redirects and the full member journey.',back:'Test permission boundaries, resource delivery, monitoring and agreed CRM error recovery.',result:'Release follows shared acceptance, editor training and a tested rollback plan.',tech:['astro','django','python'],visual:'verify'}];
let handoffIndex=0;const workspace=document.querySelector('#handoff-workspace');workspace.className='handoff-workspace';workspace.innerHTML='<div class="handoff-top"><div><span class="live-dot"></span><strong>Delivery in action</strong><small>ONE RESOURCE / FOUR HANDOFFS</small></div><button class="button" id="handoff-reset">Restart '+icon('left')+'</button></div><div class="handoff-steps" role="tablist" aria-label="Resource delivery steps">'+handoffs.map((s,i)=>'<button id="handoff-tab-'+i+'" role="tab" aria-controls="handoff-panel" aria-selected="'+(i===0)+'" tabindex="'+(i===0?0:-1)+'" data-handoff="'+i+'"><span>'+icon(s.icon)+'</span><small>0'+(i+1)+'</small><strong>'+s.name+'</strong></button>').join('')+'</div><div id="handoff-panel" class="handoff-panel" role="tabpanel" aria-labelledby="handoff-tab-0"><div class="handoff-preview" id="handoff-preview"></div><div class="handoff-detail"><span class="kicker" id="handoff-count"></span><h3 id="handoff-title"></h3><div class="handoff-roles"><div><span class="role-label">'+icon('layout')+' FRONTEND</span><p id="handoff-front"></p></div><div><span class="role-label">'+icon('shield')+' BACKEND</span><p id="handoff-back"></p></div></div><div class="handoff-result" role="status" id="handoff-result"></div><div class="handoff-tech" id="handoff-tech"></div><button id="handoff-next" class="button primary">Next handoff '+icon('arrow')+'</button></div></div><div class="handoff-boundary">'+icon('people')+' Out Leadership approves content, access rules and acceptance. The backend owner confirms effort and milestones.</div>';
function handoffVisual(i){const scenes=['<div class="handoff-editor"><span class="kicker">APPROVED RESOURCE TEMPLATE</span><div class="mock-field">Title <strong>Leadership toolkit</strong></div><div class="mock-field">Summary <strong>Practical insights for members</strong></div><div class="mock-field">Visibility <strong>Members only '+icon('lock')+'</strong></div><span class="mock-publish">'+icon('check')+' Content ready for review</span></div>','<div class="permission-scene"><span class="large-icon">'+icon('shield')+'</span><h4>Who can open this resource?</h4><div>'+icon('globe')+' Public visitor <strong>Summary only</strong></div><div>'+icon('people')+' Verified member <strong>Full resource</strong></div><small>Checked by the server on every request.</small></div>','<div class="member-scene"><span class="kicker">MEMBER SPACE</span><h4>Your resource. Ready.</h4><div class="member-resource">'+icon('book')+'<div><strong>Leadership toolkit</strong><small>Verified member access</small></div>'+icon('check')+'</div><div class="member-resource">'+icon('calendar')+'<div><strong>Upcoming events</strong><small>Relevant to your membership</small></div>'+icon('arrow')+'</div><span class="mock-publish">'+icon('devices')+' Clear on every screen</span></div>','<div class="acceptance-scene"><span class="large-icon">'+icon('check')+'</span><h4>Ready means verified.</h4>'+['Editors can publish','Members get the right access','Public content is discoverable','The team knows how to operate it'].map(t=>'<div>'+icon('check')+t+'</div>').join('')+'</div>'];return windowFrame('Illustrative handoff · no live services',scenes[i])}
function setHandoff(i){handoffIndex=i;const s=handoffs[i];document.querySelectorAll('[data-handoff]').forEach((b,n)=>{b.setAttribute('aria-selected',n===i);b.tabIndex=n===i?0:-1});document.querySelector('#handoff-panel').setAttribute('aria-labelledby','handoff-tab-'+i);document.querySelector('#handoff-preview').innerHTML=handoffVisual(i);document.querySelector('#handoff-count').textContent='HANDOFF '+(i+1)+' OF 4';document.querySelector('#handoff-title').textContent=s.name;document.querySelector('#handoff-front').textContent=s.front;document.querySelector('#handoff-back').textContent=s.back;document.querySelector('#handoff-result').innerHTML=icon('check')+'<span>'+s.result+'</span>';document.querySelector('#handoff-tech').innerHTML=s.tech.map(techBadge).join('');document.querySelector('#handoff-next').innerHTML=(i===3?'Start again':'Next handoff')+icon(i===3?'left':'arrow')}
document.querySelectorAll('[data-handoff]').forEach((b,i)=>{b.onclick=()=>setHandoff(i);b.onkeydown=e=>{let n;if(e.key==='ArrowRight')n=(i+1)%4;if(e.key==='ArrowLeft')n=(i+3)%4;if(e.key==='Home')n=0;if(e.key==='End')n=3;if(n!==undefined){e.preventDefault();setHandoff(n);document.querySelector('[data-handoff="'+n+'"]').focus()}}});document.querySelector('#handoff-next').onclick=()=>setHandoff((handoffIndex+1)%4);document.querySelector('#handoff-reset').onclick=()=>setHandoff(0);setHandoff(0);
document.querySelectorAll('[data-layer="astro"]>.icon-badge,[data-layer="cms"]>.icon-badge,[data-layer="django"]>.icon-badge').forEach(el=>{const k=el.parentElement.dataset.layer;el.innerHTML='<img src="assets/'+({astro:'astro',cms:'storyblok',django:'django'}[k])+'.svg" alt="" width="28" height="28">'});
